import itertools
L=[[int(x) for x in s] for s in ['1111','1000','1011','0010']]; R=[[int(x) for x in s] for s in ['1010','1100','0011','1100']]; Z=[[int(x) for x in s] for s in ['0000','0011','0100','1001']]
def trans(A,k):
 B=[row[:] for row in A]
 for _ in range(k%4): B=[list(row) for row in zip(*B[::-1])]
 if k>=4: B=[row[::-1] for row in B]
 return B
def fmt(A): return '/'.join(''.join(map(str,r)) for r in A)
for a in range(8):
 for b in range(8):
  X,Y=trans(L,a),trans(R,b)
  for op,f in [('and',lambda x,y:x&y),('or',lambda x,y:x|y),('xor',lambda x,y:x^y),('L-R',lambda x,y:x& (1-y)),('R-L',lambda x,y:y& (1-x))]:
   if [[f(X[i][j],Y[i][j]) for j in range(4)] for i in range(4)]==Z:
    print('match',a,b,op)
print('L',fmt(L),'R',fmt(R),'xor',fmt([[L[i][j]^R[i][j] for j in range(4)] for i in range(4)]))
# direct coord overlap/sets
for op in ['intersection','union','xor','L-R','R-L']:
 sL={(i,j) for i in range(4) for j in range(4) if L[i][j]}; sR={(i,j) for i in range(4) for j in range(4) if R[i][j]}
 s={'intersection':sL&sR,'union':sL|sR,'xor':sL^sR,'L-R':sL-sR,'R-L':sR-sL}[op]
 print(op,len(s),sorted((i+1,j+1) for i,j in s))
