 "content": """"Search for a deterministic row-pattern lookup rule on 4x4 ARC grids."""
from __future__ import annotations

from collections.abc import Iterable, Sequence

Grid = Sequence[Sequence[int]]


def encode_row(row: Sequence[int], *, width: int = 4) -> int:
    """Encode nonzero cells left-to-right as a width-bit integer."""
    if len(row) != width:
        raise ValueError(f"expected row width {width}, got {len(row)}")
    mask = 0
    for cell in row:
        mask = (mask << 1) | int(cell != 0)
    return mask


def encode_grid(grid: Grid, *, width: int = 4) -> tuple[int, ...]:
    if len(grid) != width or any(len(row) != width for row in grid):
        raise ValueError(f"expected a {width}x{width} grid")
    return tuple(encode_row(row, width=width) for row in grid)


def decode_row(mask: int, *, width: int = 4, color: int = 1) -> list[int]:
    if mask < 0 or mask >= (1 << width):
        raise ValueError("row mask does not fit width")
    return [color if mask & (1 << (width - 1 - i)) else 0 for i in range(width)]


def fit_lookup(examples: Iterable[tuple[Grid, Grid]], *, width: int = 4) -> dict[int, int] | None:
    """Fit shared row-mask -> row-mask mapping across aligned input/output rows.

    Returns None if dimensions differ or the same input row requires two outputs.
    Unseen patterns are intentionally not guessed.
    """
    rule: dict[int, int] = {}
    seen = False
    for inp, out in examples:
        seen = True
        try:
            in_rows, out_rows = encode_grid(inp, width=width), encode_grid(out, width=width)
        except (TypeError, ValueError):
            return None
        for src, dst in zip(in_rows, out_rows):
            if src in rule and rule[src] != dst:
                return None
            rule[src] = dst
    return rule if seen else None


def apply_lookup(grid: Grid, rule: dict[int, int], *, width: int = 4, color: int = 1) -> list[list[int]] | None:
    """Apply a fitted lookup; return None if any row pattern was unseen."""
    try:
        rows = encode_grid(grid, width=width)
    except (TypeError, ValueError):
        return None
    if any(row not in rule for row in rows):
        return None
    return [decode_row(rule[row], width=width, color=color) for row in rows]


def evaluate_lookup(examples: Iterable[tuple[Grid, Grid]], tests: Iterable[Grid], *, width: int = 4) -> dict:
    """Fit and report exact-grid accuracy plus whether test rows are covered."""
    pairs = list(examples)
    rule = fit_lookup(pairs, width=width)
    if rule is None:
        return {"consistent": False, "rule": None, "train_exact": 0.0, "test_predictions": []}
    train_exact = sum(apply_lookup(x, rule, width=width) == [list(r) for r in y] for x, y in pairs)
    preds = [apply_lookup(grid, rule, width=width) for grid in tests]
    return {"consistent": True, "rule": rule, "train_exact": train_exact / len(pairs), "test_predictions": preds}


if __name__ == "__main__":
    # Tiny executable sanity demo: swap the two possible single-pixel rows.
    examples = [
        ([[1, 0, 0, 0]] * 4, [[0, 0, 0, 1]] * 4),
        ([[0, 0, 0, 1]] * 4, [[1, 0, 0, 0]] * 4),
    ]
    result = evaluate_lookup(examples, [[[1, 0, 0, 0]] * 4])
    print(result)
    assert result["consistent"] and result["train_exact"] == 1.0
