tL='0100/0100/1000/1101';tR='1011/0001/1100/0001'
def p(s):return [int(c) for c in s.replace('/','')]
def shift(a,dy,dx,wrap=False):
 out=[]
 for r in range(4):
  for c in range(4):
   rr,cc=r+dy,c+dx
   if wrap: out.append(a[(rr%4)*4+cc%4])
   else: out.append(a[rr*4+cc] if 0<=rr<4 and 0<=cc<4 else 0)
 return out
def fmt(a):return '/'.join(''.join(map(str,a[r*4:r*4+4])) for r in range(4))
for wrap in (False,True):
 found=[]
 for dly,dlx,dry,drx in product(range(-1,2),repeat=4):
  pairs=[]
  for l,r,o in D:
   pairs.append((shift(p(l),dly,dlx,wrap),shift(p(r),dry,drx,wrap),p(o)))
  for lut in range(16):
   if all(all(((lut>>((a<<1)|b))&1)==c for a,b,c in zip(x,y,o)) for x,y,o in pairs):
    out=[(lut>>((a<<1)|b))&1 for a,b in zip(shift(p(tL),dly,dlx,wrap),shift(p(tR),dry,drx,wrap))]
    found.append((dly,dlx,dry,drx,lut,fmt(out)))
 print('wrap',wrap,'rules',len(found),'examples',found[:10])

